head.b:skin:
    /*==================================================================
  PHOENIX THEME DESIGNER VARIABLES
====================================================================

<Group description="Phoenix Theme Colors" selector="body">

<Variable name="phoenix.primary.color"
          description="Primary Accent Color"
          type="color"
          default="#ff4a57"
          value="#ff4a57"/>

<Variable name="phoenix.primary.dark"
          description="Primary Accent Hover"
          type="color"
          default="#e0323e"
          value="#e0323e"/>

<Variable name="phoenix.secondary.color"
          description="Secondary Color"
          type="color"
          default="#1a1a2e"
          value="#1a1a2e"/>

<Variable name="phoenix.background.color"
          description="Page Background"
          type="color"
          default="#f8f9fa"
          value="#f8f9fa"/>

<Variable name="phoenix.surface.color"
          description="Card Background"
          type="color"
          default="#ffffff"
          value="#ffffff"/>

<Variable name="phoenix.text.color"
          description="Primary Text"
          type="color"
          default="#2b2b2b"
          value="#2b2b2b"/>

<Variable name="phoenix.text.muted"
          description="Secondary Text"
          type="color"
          default="#6c757d"
          value="#6c757d"/>

<Variable name="phoenix.border.color"
          description="Border Color"
          type="color"
          default="#e9ecef"
          value="#e9ecef"/>

</Group>

<Group description="Phoenix Typography" selector="body">

<Variable
    name="phoenix.brand.font"
    description="Brand Font"
    type="font"
    default="normal normal 700 30px Playfair Display, serif"
    value="normal normal 700 30px Playfair Display, serif"/>

<Variable
    name="phoenix.heading.font"
    description="Heading Font"
    type="font"
    default="normal normal 700 48px Playfair Display, serif"
    value="normal normal 700 48px Playfair Display, serif"/>

<Variable
    name="phoenix.body.font"
    description="Body Font"
    type="font"
    default="normal normal 16px Inter, sans-serif"
    value="normal normal 16px Inter, sans-serif"/>

<Variable
    name="phoenix.ui.font"
    description="UI Font"
    type="font"
    default="normal normal 16px Inter, sans-serif"
    value="normal normal 16px Inter, sans-serif"/>

</Group>

*/
    /* ==========================================================================
       VARIABLES, RESET, & BASE STYLES
       ========================================================================== */
    :root {

    --primary-color: $(phoenix.primary.color);
    --primary-dark: $(phoenix.primary.dark);
    --secondary-color: $(phoenix.secondary.color);

    --bg-color: $(phoenix.background.color);
    --card-bg: $(phoenix.surface.color);

    --text-color: $(phoenix.text.color);
    --text-muted: $(phoenix.text.muted);

    --border-color: $(phoenix.border.color);

    --font-sans: $(phoenix.body.font);

    --max-width: 1200px;

    --transition: all 0.3s cubic-bezier(0.4,0,0.2,1);

    --shadow: 0 4px 6px -1px rgba(0,0,0,.1),
              0 2px 4px -1px rgba(0,0,0,.06);

    --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.1),
                 0 4px 6px -2px rgba(0,0,0,.05);

    /* Compatibility Layer */

    --primary: var(--primary-color);

    --surface: var(--card-bg);

    --surface-alt: var(--bg-color);

    --text: var(--text-color);

    --text-light: var(--text-muted);

    --border: var(--border-color);

    --font: var(--font-sans);

    --font-brand: $(phoenix.brand.font);

    --font-heading: $(phoenix.heading.font);

    --font-body: $(phoenix.body.font);

    --font-ui: $(phoenix.ui.font);

    --shadow-sm: var(--shadow);

    --shadow-md: var(--shadow-lg);

}

    * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
    }

    body {
        font: var(--font-body);
        background-color: var(--surface-alt);
        color: var(--text);
        line-height: 1.6;
        overflow-x: hidden;
    }

    a {
        color: inherit;
        text-decoration: none;
        transition: var(--transition);
    }

    img {
        max-width: 100%;
        height: auto;
    }

    /* Container Utility */
    .container {
        width: 100%;
        max-width: var(--max-width);
        margin: 0 auto;
        padding: 0 24px;
    }

    .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
    }

    .skip-link {
        position: absolute;
        top: -100px;
        left: 20px;
        background: var(--primary);
        color: #ffffff;
        padding: 10px 20px;
        z-index: 9999;
        font-weight: 600;
        border-radius: 4px;
        transition: top 0.2s;
    }
    .skip-link:focus {
        top: 20px;
    }

    /* ==========================================================================
       MODERN NAVIGATION & HEADER (FLEXBOX)
       ========================================================================== */
    .navbar {
        background: var(--surface);
        border-bottom: 1px solid var(--border);
        position: relative;
        top: 0;
        z-index: 1000;
        padding: 16px 0;
    }
    .navbar .header,
    .navbar .main-menu-section,
    .navbar .widget {
        margin: 0;
        padding: 0;
        min-height: 0;
    }
    .nav-container {
        display: flex;
        justify-content: space-between;
        align-items: center;
    }
    .logo {
        font: var(--font-brand);
        font-size: 30px;
        font-weight: 800;
        color: var(--text);
        letter-spacing: -0.03em;
        white-space: nowrap;
    }
    .logo span {
        color: var(--primary);
    }
    .site-navigation {
        display: flex;
        align-items: center;
        position: relative;
        z-index: 99;
    }
    .nav-menu {
       display: flex;
       gap: 1.5rem;
       list-style: none;
       margin: 0;
       padding: 0px 0px 0px 25px;
       position: relative;
       z-index: 100;
    }

    .nav-item a {
       font: var(--font-ui);
       text-decoration: none;
       color: #333333;
       transition: color 0.2s ease;
    }

    .nav-item.active a {
       color: var(--primary); 
       font-weight: bold;
    }

    .nav-menu a {
        font: var(--font-ui);
        color: var(--text);
        font-weight: 500;
        font-size: 15px;
        transition: color .25s ease, opacity .25s ease;
    }

    .nav-menu a:hover, .nav-menu a[aria-current="page"] {
        color: var(--primary);
    }
    .nav-right {
        display: flex;
        align-items: center;
        gap: 20px;
    }

    .search-box {
        display: flex;
        align-items: center;
        background-color: var(--surface-alt);
        border: 1px solid var(--border);
        border-radius: 30px;
        padding: 6px 16px;
        gap: 10px;
    }
    .search-box svg {
        color: var(--text-light);
        display: flex;
    }
    .search-box input {
        font: var(--font-ui);
        border: none;
        background: transparent;
        outline: none;
        font-size: 14px;
        color: var(--text);
    }
    .subscribe-btn {
        font: var(--font-ui);
        background-color: var(--primary);
        color: #ffffff;
        padding: 10px 24px;
        border-radius: 30px;
        font-weight: 600;
        font-size: 14px;
    }
    .subscribe-btn:hover {
        background-color: var(--primary-dark);
        transform: translateY(-1px);
    }

    .search-toggle {
        display:none;
    }

    .search-close{
            display:none;
        }
.nav-toggle {
    display:none;

    width:48px;
    height:48px;

    background:none;
    border:none;

    cursor:pointer;

    align-items:center;
    justify-content:center;

    flex-direction:column;

    gap:5px;

    padding:4px;

    z-index:1001;

    transition:var(--transition);
}
    .nav-toggle-line {
        width: 24px;
        height: 2px;
        background-color: var(--text);
        transition: var(--transition);
    }

    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(1) {
        transform: translateY(8px) rotate(45deg);
    }
    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(2) {
        opacity: 0;
    }
    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(3) {
        transform: translateY(-8px) rotate(-45deg);
    }

    .h1,
    .h2,
    .h3,
    .h4,
    .h5,
    .h6 {
        font-family: inherit;
    }

    /* ==========================================================================
       HERO & FEATURED SECTION (GRID & FLEXBOX)
       ========================================================================== */

    .hero-title,
    .article-title,
    .section-header h2,
    .hero-spotlight h2,
    .hero-spotlight-content h2,
    .category-card h3,
    .editor-card h3,
    .article-card h3,
    .post-title,
    .post-body h2,
    .post-body h3,
    .post-body h4,
    .newsletter-box h2,
    .footer-title,
    .editorial-content h2,
    .editorial-content h3,
    .editorial-references h4,
    .comments h4,
    .author-card-info h4 {
        font-family: var(--font-heading);
    }

    .hero-title,
    .article-title,
    .post-title {
        letter-spacing: -0.02em;
    }

    .hero {
        padding: 64px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .hero-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 60px;
        align-items: center;
    }
    .hero-content {
        display: flex;
        flex-direction: column;
    }
    .hero-label {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1.5px;
        margin-bottom: 16px;
    }
    .hero-title {
        font-size: 52px;
        font-weight: 800;
        line-height: 1.15;
        color: var(--text);
        letter-spacing: -1.5px;
        margin-bottom: 24px;
    }
    .hero-description {
        font-size: 18px;
        color: var(--text-light);
        margin-bottom: 32px;
        max-width: 800px;
    }
    .hero-buttons {
        display: flex;
        gap: 16px;
        margin-bottom: 40px;
    }
    .btn {
        font: var(--font-ui);
        display: inline-block;
        padding: 14px 32px;
        border-radius: 30px;
        font-weight: 600;
        font-size: 15px;
        text-align: center;
    }
    .btn-primary {
        background-color: var(--primary);
        color: #ffffff;
    }
    .btn-primary:hover {
        background-color: var(--primary-dark);
        transform: translateY(-1.5px);
    }
    .btn-outline {
        border: 2px solid var(--border);
        color: var(--text);
    }
    .btn-outline:hover {
        background-color: var(--surface-alt);
        border-color: var(--text);
        transform: translateY(-1.5px);
    }

    .btn-secondary {
      background-color: var(--primary);
      display: inline-block;
      padding: 14px 32px;
      border: 2px solid var(--primary);
      border-radius: 30px;
      background: var(--surface);
      color: #ffffff;
      font-weight: 600;
      font-size: 15px;
      text-align: center;
      transition: all var(--transition-fast);
    }

    .btn-secondary:hover {
        background: var(--primary);
        border-color: var(--primary);
        color: #fff;
        transform: translateY(-1.5px);
    }

    .input,
    .textarea,
    .select,
    .button {
        font: var(--font-ui);
    }

    .hero-community {
        display: flex;
        align-items: center;
        gap: 16px;
    }

    .hero-actions {
        display: flex;
        gap: 16px;
        flex-wrap: wrap;
        align-items: center;
        margin-top: 32px;
    }

    .avatar-group {
        display: flex;
    }
    .avatar {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background-color: var(--text);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 700;
        font-size: 12px;
        border: 2px solid #ffffff;
        margin-left: -12px;
    }
    .avatar:first-child {
        margin-left: 0;
    }
    .hero-community p {
        font-size: 13px;
        color: var(--text-light);
    }

    .hero-spotlight {
        background-color: var(--surface-alt);
        border-radius: 20px;
        padding: 32px;
        border: 1px solid var(--border);
        display: flex;
        flex-direction: column;
        transition: var(--transition);
    }
    .hero-spotlight:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow-lg);
    }
    .hero-spotlight-image {
        height: 240px;
        background: var(--surface-alt);
        border-radius: 14px;
        margin-bottom: 24px;
        position: relative;
        overflow: hidden;
    }
    .hero-spotlight-overlay {
        position: absolute;
        top: 16px;
        left: 16px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 4px 14px;
        border-radius: 20px;
        font-size: 12px;
        font-weight: 700;
        text-transform: uppercase;
    }
    .hero-spotlight h2 {
        font-size: 24px;
        line-height: 1.3;
        margin-bottom: 12px;
        color: var(--text);
    }
    .hero-spotlight p {
        color: var(--text-light);
        font-size: 15px;
        margin-bottom: 24px;
    }
    .hero-spotlight-meta {
        display: flex;
        gap: 16px;
        font-size: 13px;
        color: var(--text-light);
        margin-bottom: 24px;
    }

    /* ==========================================================================
       UTILITY COMPONENTS & ZONES
       ========================================================================== */
    .ad-zone {
        padding: 24px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .ad-placeholder {
        text-align: center;
    }
    .ad-label {
        font-size: 11px;
        color: var(--text-light);
        text-transform: uppercase;
        letter-spacing: 1.5px;
        display: block;
        margin-bottom: 10px;
    }
    .ad-box {
        background-color: var(--surface-alt);
        border: 2px dashed var(--border);
        padding: 36px;
        font-size: 14px;
        color: var(--text-light);
        border-radius: 12px;
        font-weight: 500;
    }

    .announcement-bar {
        background-color: var(--text);
        color: #ffffff;
        padding: 12px 0;
        font-size: 14px;
    }
    .announcement-content {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 16px;
        flex-wrap: wrap;
    }
    .announcement-badge {
        background-color: var(--primary);
        padding: 3px 10px;
        border-radius: 6px;
        font-weight: 700;
        font-size: 11px;
        text-transform: uppercase;
    }
    .announcement-link {
        color: var(--primary);
        font-weight: 600;
        text-decoration: underline;
    }

    .quick-access {
        padding: 24px 0;
        background-color: var(--surface-alt);
        border-bottom: 1px solid var(--border);
    }
    .quick-access-wrapper {
        display: flex;
        align-items: center;
        gap: 12px;
        flex-wrap: wrap;
    }
    .quick-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text);
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-right: 12px;
    }
    .quick-pill {
        background: var(--surface);
        border: 1px solid var(--border);
        padding: 8px 18px;
        border-radius: 24px;
        font-size: 13px;
        font-weight: 600;
        color: var(--text);
    }
    .quick-pill:hover {
        background-color: var(--primary);
        color: #ffffff;
        border-color: var(--primary);
    }

    .stats {
        padding: 36px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .stats-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 24px;
    }
    .stat-card {
        text-align: center;
        padding: 16px;
    }
    .stat-card h2 {
        font-size: 42px;
        font-weight: 800;
        color: var(--primary);
        margin-bottom: 6px;
        letter-spacing: -1px;
    }
    .stat-card p {
        color: var(--text-light);
        font-size: 14px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

    /* ==========================================================================
       SECTION WRAPPERS & GRIDS
       ========================================================================== */
    .section {
        padding: 56px 0;
    }
    .section-header {
        margin-bottom: 48px;
        max-width: 650px;
    }
    .section-header h2 {
        font-size: 36px;
        color: var(--text);
        letter-spacing: -1px;
        margin-bottom: 12px;
    }
    .section-header p {
        color: var(--text-light);
        font-size: 16px;
    }

    .category-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .category-card {
        background: var(--surface);
        padding: 36px;
        border-radius: 16px;
        border: 1px solid var(--border);
        display: flex;
        flex-direction: column;
        transition: var(--transition);
    }
    .category-card:hover {
        transform: translateY(-6px);
        box-shadow: var(--shadow-lg);
        border-color: rgba(255, 74, 87, 0.2);
    }
    .category-icon {
        background-color: var(--surface-alt);
        color: var(--primary);
        width: 54px;
        height: 54px;
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 800;
        font-size: 14px;
        margin-bottom: 24px;
        border: 1px solid var(--border);
    }
    .category-card h3 {
        font-size: 20px;
        color: var(--text);
        margin-bottom: 12px;
    }
    .category-card p {
        color: var(--text-light);
        font-size: 15px;
        margin-bottom: 24px;
        flex-grow: 1;
    }
    .category-link {
        font-weight: 700;
        color: var(--primary);
        font-size: 14px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

    .featured-story {
        background-color: var(--surface-alt);
    }
    .featured-story-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 60px;
        align-items: center;
    }
    .hero-spotlight-image {
        height: 400px;
        background: var(--surface-alt);
        border-radius: 20px;
        position: relative;
        overflow: hidden;
    }

    .hero-spotlight-image-link {
      display: block;
      width: 100%;
      height: 100%;
    }

    .hero-spotlight-img {
      display: block;
      position: relative;
      z-index: 1;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .hero-spotlight-img:hover {
      transform: scale(1.05);
      transition: var(--transition);
    }

    .hero-spotlight-fallback {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--surface-alt), #DCE7FF);
      color: var(--text-light);
      font-family: var(--font-heading);
      font-size: 26px;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .hero-spotlight-badge {
        position: absolute;
        z-index: 2;
        top: 24px;
        left: 24px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 6px 16px;
        border-radius: 24px;
        font-weight: 700;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }
    .story-category {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1px;
        margin-bottom: 16px;
    }

    .hero-spotlight-content {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: flex-start;
    }

    .hero-spotlight-content h2 {
        font-size: 40px;
        color: var(--text);
        margin-bottom: 20px;
        line-height: 1.2;
        letter-spacing: -1px;
    }
    .hero-spotlight-content p {
        color: var(--text-light);
        margin-bottom: 28px;
        font-size: 16px;
        line-height: 1.7;
    }
    .hero-spotlight-meta {
        display: flex;
        gap: 16px;
        align-items: center;
        margin-bottom: 32px;
        color: var(--text-light);
        font-size: 14px;
    }



    /* Editors Picks Grid */
    .editors-picks {
        background: var(--surface);
    }
    .editors-picks .section-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        max-width: none;
    }
    .section-label {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1px;
        margin-bottom: 8px;
    }
    .editor-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
        counter-reset: editor-card;
    }
    .editor-card {
        display: flex;
        gap: 24px;
        padding: 24px;
        border-radius: 16px;
        border: 1px solid var(--border);
        transition: var(--transition);
        counter-increment: editor-card;
    }
    .editor-card:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow);
    }
    .editor-number {
        font-size: 36px;
        font-weight: 800;
        color: var(--border);
        line-height: 1;
    }
    .editor-number::before {
        content: counter(editor-card, decimal-leading-zero);
    }
    .editor-category {
        color: var(--primary);
        font-weight: 700;
        font-size: 11px;
        text-transform: uppercase;
        margin-bottom: 6px;
        letter-spacing: 0.5px;
    }
    .editor-card h3 {
        font-size: 18px;
        margin-bottom: 10px;
        line-height: 1.4;
        color: var(--text);
    }
    .editor-card h3 a {
        color: inherit;
        text-decoration: none;
    }
    .editor-card h3 a:hover {
        color: var(--primary);
    }
    .editor-card p {
        font-size: 14px;
        color: var(--text-light);
        align-self: flex-start;
    }

    .editor-card-link {
        display: flex;
        align-items: flex-start;
        gap: 20px;
        width: 100%;
        height: 100%;
        color: inherit;
        text-decoration: none;
    }

    .editor-content {
        flex: 1;
        display: flex;
        flex-direction: column;
        align-self: stretch;
        min-width: 0;
    }

    .editor-image {
        width: 84px;
        height: 84px;
        flex-shrink: 0;
        overflow: hidden;
        border-radius: 12px;
        background: var(--surface-alt);
    }

    .editor-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform .35s ease;
    }

    .editor-card:hover .editor-image img {
        transform: scale(1.05);
    }

    .editor-header {
        display: flex;
        align-items: flex-start;
        gap: 18px;
        margin-bottom: 18px;
    }

    .editor-title {
        margin: 0;
        margin-bottom: 8px;
        font-size: 1.15rem;
        line-height: 1.35;
        font-weight: 700;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
    }

    .editor-meta {
        display: flex;
        align-items: center;
        gap: 10px;
        margin: 6px 0 8px;
    }

    .editor-snippet {
        margin: 0;
        margin-top: 12px;
        color: var(--text-light);
        line-height: 1.7;
        display: -webkit-box;
        -webkit-line-clamp: 4;
        -webkit-box-orient: vertical;
        overflow: hidden;
        flex-grow: 0;
    }

    /* Latest Articles Grid */
    .flex-between {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
    }
    .mb-5 {
        margin-bottom: 40px;
    }
    .article-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .article-card {
        display: flex;
        flex-direction: column;
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 20px;
        overflow: hidden;
        transition: var(--transition);
    }

    .article-card:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow-lg);
    }
    .article-image {
        height: 220px;
        background: var(--surface-alt);
        position: relative;
        overflow: hidden;
        transition: transform .35s ease;
    }

    .article-card:hover .article-image img{
        transform: scale(1.03);
    }
    .article-badge {
        position: absolute;
        top: 16px;
        left: 16px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 4px 12px;
        border-radius: 20px;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
    }
    .article-content {
        padding: 28px;
        display: flex;
        flex-direction: column;
        flex-grow: 1;
        gap: 16px;
    }
    .article-meta {
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: .9rem;
        color: var(--text-light);
    }
    .article-card h3 {
        margin: 0;
        font-size: 1.7rem;
        line-height: 1.3;
        font-weight: 700;
    }
    .article-card p {
        margin: 0;
        color: var(--text-light);
        line-height: 1.8;
    }
    .article-link {
        margin-top: auto;
        font-weight: 700;
        color: var(--primary);
        text-decoration: none;
    }

    .article-link:hover {
        text-decoration: underline;
    }

    /* ==========================================
   ARTICLE HERO
========================================== */
.article-hero {
    padding: 32px 0 16px;
}

.article-header {
    max-width: var(--max-width);
    margin: 0 auto 1.5rem;
    padding: 0 24px;
}

.article-eyebrow {
    display: inline-block;
    margin-bottom: 10px;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--primary);
}

.article-title {
    margin: 0;
    font-size: clamp(2.6rem, 5vw, 4rem);
    line-height: 1.08;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: var(--text);
}

.article-summary {
    margin-top: 1.5rem;
    margin-bottom: 2rem;
    max-width: 720px;
    font-size: 1.2rem;
    line-height: 1.8;
    font-weight: 400;
    color: var(--text-light);
}

.article-meta time,
.article-meta span {
    display: inline-flex;
    align-items: center;
}

    /* ==========================================================================
       DYNAMIC BLOGGER WRAPPER STYLES & COMMENTS DESIGN SYSTEM
       ========================================================================== */
    .blog-posts {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
    }
    .post-outer {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 16px;
        overflow: hidden;
        transition: var(--transition);
    }
    .post-outer:hover {
        transform: translateY(-5px);
        box-shadow: var(--shadow-lg);
    }

    /* Single Post Page Styles */
    .post-container {
        max-width: 800px;
        margin: 0 auto;
        background: var(--surface);
        padding: 72px 80px;
        border-radius: 16px;
        border: 1px solid var(--border);
    }
    .post-title {
        font-size: 42px;
        color: var(--text);
        margin-bottom: 24px;
        line-height: 1.2;
    }
    .post-body {
        font-size: 17px;
        line-height: 1.8;
        color: var(--text);
    }
    .post-body::after {
        content: "";
        display: block;
        clear: both;
    }
    .post-body img {
        border-radius: 12px;
        margin: 8px 32px 24px 0;
        float: left;
        max-width: 50%;
        height: auto;
    }
    .post-body h2 {
        margin: 40px 0 1.5rem;
        color: var(--text);
    }
    .post-body h3 {
        margin: 3rem 0 1.25rem;
        color: var(--text);
    }
    .post-body h4 {
        margin: 2.25rem 0 1rem;
        color: var(--text);
    }
    .post-body p {
        margin-bottom: 20px;
    }
    .post-body ul, .post-body ol {
        margin: 16px 0;
        padding-left: 24px;
    }
    .post-body li {
        margin-bottom: 8px;
    }
    .post-body a {
        color: var(--primary);
        text-decoration: underline;
    }
    .post-body blockquote {
        border-left: 4px solid var(--primary);
        padding-left: 20px;
        margin: 24px 0;
        color: var(--text-light);
        font-style: italic;
    }
    .post-body pre {
        background: var(--surface-alt);
        padding: 20px;
        border-radius: 8px;
        overflow-x: auto;
        margin: 20px 0;
    }
    .post-body code {
        background: var(--surface-alt);
        padding: 2px 6px;
        border-radius: 4px;
        font-size: 0.9em;
    }
/* ==========================================================================
   PHOENIX HOME HERO
   ========================================================================== */

.home-hero{
    padding:4rem 0 3rem;
}

.home-hero__content{
    max-width:760px;
}

.home-hero__eyebrow{
    display:inline-block;
    margin-bottom:1rem;
    font-size:.85rem;
    font-weight:700;
    letter-spacing:.12em;
    text-transform:uppercase;
    color:var(--primary);
}

.home-hero__title{
    font-size:clamp(2.5rem,5vw,4rem);
    line-height:1.1;
    font-weight:800;
    margin-bottom:1.5rem;
    letter-spacing:-.03em;
}

.home-hero__description{
    max-width:680px;
    font-size:1.2rem;
    line-height:1.8;
    color:var(--text-light);
    margin-bottom:2rem;
}

.home-hero__actions{
    display:flex;
    gap:1rem;
    flex-wrap:wrap;
}
    /* Author Card Styling */

    .author-card-avatar {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        background: var(--primary);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 22px;
        font-weight: 700;
        flex-shrink: 0;
    }
    .author-card-info h4 {
        font-size: 18px;
        color: var(--text);
        margin-bottom: 6px;
    }
    .author-card-info p {
        font-size: 14px;
        color: var(--text-light);
        margin: 0;
        line-height: 1.6;
    }

    /* Comments Section Styling Integration */
    .comments-section-wrap {
        margin-top: 48px;
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 40px;
    }
    .comments h4 {
        font-size: 24px;
        color: var(--text);
        margin-bottom: 24px;
    }
    #comments-block {
        list-style: none;
        padding: 0;
        margin: 0;
    }
    .comment-author {
        font-weight: 600;
        color: var(--text);
        margin-bottom: 8px;
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 15px;
    }
    .comment-author a {
        color: var(--primary);
    }
    .comment-body {
        background: var(--surface-alt);
        padding: 16px 20px;
        border-radius: 12px;
        margin-bottom: 12px;
        color: var(--text);
        font-size: 15px;
        border: 1px solid var(--border);
    }
    .comment-footer {
        font-size: 13px;
        color: var(--text-light);
        margin-bottom: 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
    }
    .comment-footer a {
        color: var(--text-light);
    }
    .comment-footer a:hover {
        color: var(--primary);
    }
    .comment-form {
        margin-top: 32px;
        padding-top: 24px;
        border-top: 1px solid var(--border);
    }
    .comment-form h4 {
        font-size: 20px;
        color: var(--text);
        margin-bottom: 12px;
    }
    .comment-form p {
        color: var(--text-light);
        font-size: 14px;
        margin-bottom: 16px;
    }
    #comment-editor {
        background: var(--surface-alt);
        border-radius: 12px;
        border: 1px solid var(--border);
        min-height: 250px;
        width: 100%;
    }

    /* Static Page Styles */
    .static-page-container {
        width: min(1200px, calc(100% - 48px));
        margin: 0 auto;
        background: var(--surface);
        padding: 64px;
        border-radius: 20px;
        border: 1px solid var(--border);
    }

    /* ==========================================================================
       NEWSLETTER BOX
       ========================================================================== */
    .newsletter {
        background-color: var(--text);
        color: #ffffff;
        padding: 72px 0;
    }
    .newsletter-box {
        text-align: center;
        max-width: 640px;
        margin: 0 auto;
    }
    .newsletter-box h2 {
        font-size: 38px;
        font-weight: 800;
        letter-spacing: -1px;
        margin-bottom: 16px;
    }
    .newsletter-text {
        font-size: 16px;
        margin-bottom: 36px;
        color: rgba(255, 255, 255, 0.8);
    }
    .newsletter-form {
        display: flex;
        gap: 16px;
    }
    .newsletter-input {
        flex-grow: 1;
        padding: 16px 28px;
        border-radius: 30px;
        border: 1px solid rgba(255,255,255,0.1);
        outline: none;
        font: var(--font-ui);
        font-size: 15px;
        background: rgba(255, 255, 255, 0.05);
        color: white;
        transition: var(--transition);
    }
    .newsletter-input:focus {
        border-color: var(--primary);
        background: rgba(255, 255, 255, 0.1);
    }

    /* ==========================================================================
       FOOTER (GRID & FLEXBOX SYSTEM)
       ========================================================================== */
    .site-footer {
        background: var(--secondary-color);
        color: rgba(255, 255, 255, 0.72);
        padding: 64px 0 32px;
    }
    .footer-container {
        max-width: var(--max-width);
        margin: 0 auto;
        padding: 0 24px;
    }
    .footer-top {
        display: grid;
        grid-template-columns: 0.9fr 1.1fr;
        gap: 64px;
        margin-bottom: 48px;
    }
    .footer-brand {
        display: flex;
        flex-direction: column;
    }
    .footer-logo {
        font: var(--font-brand);
        font-size: 30px;
        font-weight: 800;
        letter-spacing: -0.03em;
        color: #ffffff;
        display: inline-block;
        margin-bottom: 16px;
    }
    .footer-logo span {
        color: var(--primary);
    }
    .footer-description {
        margin-bottom: 16px;
        font-size: 15px;
        line-height: 1.8;
        max-width: 340px;
    }
    .footer-tagline {
        font-size: 13px;
        line-height: 1.5;
        color: rgba(255, 255, 255, 0.45);
    }
    .footer-navigation {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .footer-title {
        color: #ffffff;
        font-size: 0.9rem;
        font-weight: 700;
        margin-bottom: 24px;
        text-transform: uppercase;
        letter-spacing: .08em;
    }
    .footer-links {
        list-style: none;
    }
    .footer-links li {
        margin-bottom: 14px;
    }
    .footer-links a {
        font: var(--font-ui);
        font-size: 0.95rem;
        color: inherit;
    }
    .footer-links a:hover {
        color: var(--primary);
        transition: color 0.25s ease;
    }
    .footer-social {
        display: flex;
        flex-direction: column;
        gap: 12px;
    }
    .footer-social a {
        font-size: 14px;
    }
    .footer-social a:hover {
        color: var(--primary);
    }
    .footer-divider {
        border: none;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
        margin-bottom: 40px;
    }
    .footer-bottom {
        display: flex;
        justify-content: space-between;
        font-size: 14px;
        text-align: center;
        flex-direction: column;
        gap: 16px;
        align-items: center;
        padding-top: 0.5rem;
    }
    .footer-copyright strong {
        color: #ffffff;
    }
    .footer-credit a {
        color: #ffffff;
        font-weight: 600;
    }
    .footer-credit a:hover {
        color: var(--primary);
    }

    /* ==========================================================================
       RESPONSIVE GRID ADAPTIONS (MEDIA QUERIES)
       ========================================================================== */
    @media (max-width: 1024px) {
        .hero-grid {
            gap: 40px;
        }
        .hero-title {
            font-size: 42px;
        }
        .category-grid, .editor-grid, .article-grid {
            gap: 24px;
        }
    }

    @media (max-width: 900px) {
        .hero-grid, .featured-story-grid, .footer-top {
            grid-template-columns: 1fr;
            gap: 48px;
        }
        .stats-grid {
            grid-template-columns: repeat(2, 1fr);
        }
        .category-grid, .editor-grid, .article-grid {
            grid-template-columns: repeat(2, 1fr);
        }
        .footer-navigation {
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
        }
    }

    @media (max-width: 768px) {
        .navbar {
            padding: 12px 0;
        }
        .hero,
        .section {
            padding: 48px 0;
        }
        .stats {
            padding: 32px 0;
        }
        .newsletter {
            padding: 56px 0;
        }
        .site-footer {
            padding: 56px 0 28px;
        }
        .nav-toggle {
            display: flex;
            order:3;
        }
        .site-navigation {
            position:absolute;
            top:100%;
            left:0;
            right:0;

            background:#fff;

            border-top:1px solid var(--border);

            display:none;

            z-index:999;
        }

        .site-navigation
        .main-menu-section,
        .site-navigation
        .widget.PageList{

            width:100%;
        }


        .navbar.is-nav-open .site-navigation {
            display: block;
            position: absolute;
            top: 100%;
            left: 0;
            width: 100%;
            background: var(--surface);
            padding: 30px 24px;
            border-bottom: 1px solid var(--border);
            box-shadow: var(--shadow-lg);
        }
        .navbar.is-nav-open .nav-menu {
            flex-direction: column;
            gap: 20px;
        }
        .navbar.is-nav-open .nav-menu a {
            font-size: 18px;
            display: block;
        }
        .nav-right {
            gap:12px;
            display:flex;
            align-items:center;

        }
        .nav-right .search-box, .nav-right .subscribe-btn {
            display: none;
        }

        .category-grid,
        .editor-grid,
        .article-grid,
        .footer-navigation,
        .stats-grid,
        .blog-posts {
            grid-template-columns: 1fr;
            gap: 24px;
        }
        .hero-title {
            font-size: 36px;
        }
        .newsletter-form {
            flex-direction: column;
            gap: 12px;
        }
        .newsletter-input {
            width: 100%;
        }
        .post-container, .static-page-container {
            padding: 24px;
        }
        .post-title {
            font-size: 32px;
        }
        .post-body img {
            float: none;
            max-width: 100%;
            margin: 24px 0;
            display: block;
        }

        .home-hero{
            padding:2.5rem 0;
        }

        .home-hero__title {
            font-size:2.2rem;
        }

        .home-hero__description {
            font-size:1rem;
        }

        .home-hero__actions {
            flex-direction:column;
            align-items:stretch;
        }

        /* Latest Articles Header */
        .flex-between{
            flex-direction:column;
            align-items:flex-start;
            gap:1rem;
        }

        .flex-between .btn {
            margin-top: 0;
            align-self: flex-start;
        }

        .home-hero__actions .btn {
            width:100%;
        }

        .flex-between {
            flex-wrap: wrap;
            align-items: flex-start;
        }

        .flex-between h2 {
            margin: 0;
            width: 100%;
        }

        .flex-between .btn {
            margin-top: .5rem;
            align-self: flex-start;
        }

        .latest-articles-header {
            margin-bottom: 2rem;
        }

        /* Mobile Search Button */
        .search-toggle {
            display:flex;
            align-items:center;
            justify-content:center;
            width:44px;
            height:44px;
            border:none;
            background:transparent;
            cursor:pointer;
            font-size:22px;
            color:var(--text);
            flex-shrink:0;
            order:1;
        }

        .search-toggle:hover{
            color:var(--primary);
        }

        .search-box{
            display:none;
            order:2;
            position:relative;
        }

       .search-box.is-open{
            display:flex;
            align-items:center;
            flex:1;
            margin:0 12px;
        }

        .search-box.is-open input{
            width:100%;
        }

        .search-close{
            display:none;
            position:absolute;
            right:12px;
            top:50%;
            transform:translateY(-50%);
            border:none;
            background:transparent;
            font-size:22px;
            cursor:pointer;
            color:var(--text-light);
        }

        .search-box.is-open .search-close{
            display:block;
        }

        .search-box input{
            padding-right:36px;
        }


    }
 /* ==========================================================================
   PHOENIX MOBILE MENU
 ========================================================================== */


@media (max-width: 768px) {

    .site-navigation {

        display: none;

        position: absolute;
        top: 100%;
        left: 0;
        right: 0;

        background: var(--surface);

        border-top: 1px solid var(--border);

        box-shadow: var(--shadow-md);

        z-index: 1000;
    }

    .site-navigation.active {
        display: block;
    }

    .site-navigation .nav-menu {
        display: flex;
        flex-direction: column;
        gap: 0;
        padding: 1rem 0;
    }

    .nav-item a {
        display: block;
        padding: 1rem 1.5rem;
    }
}
/* ==========================================================================
   PHOENIX MOBILE NAVIGATION
   ========================================================================== */


.nav-toggle-line{

    width:24px;
    height:2px;

    background:var(--text);

    border-radius:999px;

    transition:var(--transition);

}

 /* ==========================================================================
   PHOENIX AUTHOR CARD
   ========================================================================== */

.author-card {
    max-width: var(--max-width);
    margin: 3rem auto;
    padding: 2rem;
    transition:var(--transition);
    background: var(--surface);
    border: 1px solid rgba(15, 23, 42, 0.04);
    border-radius: 28px;
    box-shadow: 0 14px 42px rgba(15, 23, 42, 0.08);
}

.author-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 24px 60px rgba(15,23,42,.12);

}

/* ==========================================================================
   HEADER
   ========================================================================== */

.author-card__header {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.author-card__avatar {
    width: 124px;
    height: 124px;
    flex-shrink: 0;
}

.author-card__avatar svg {
    display: block;
    width: 100%;
    height: 100%;
}

.author-card__identity {
    flex: 1;
}

.author-card__name {
    margin: 0 0 0.75rem;
    font-size: 2.2rem;
    font-weight: 800;
    color: var(--text);
    line-height: 1.1;
    letter-spacing: -0.02em;
}

/* ==========================================================================
   BADGE
   ========================================================================== */

.author-card__badge {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 1rem;
    border-radius: 999px;

    background: #E9F0FF;
    color: #3F4E73;

    font-size: 0.95rem;
    font-weight: 600;
}

.author-card__badge svg {
    width: 16px;
    height: 16px;
}

/* ==========================================================================
   BIO
   ========================================================================== */

.author-card__bio {
    margin-bottom: 2rem;
    padding:1.35rem 2rem;

    background: #F7F9FF;
    border: 1px solid #E8EDF9;
    border-radius: 999px;

    color: var(--text);

    font-size:1.18rem;
    font-weight:500;
    line-height: 1.65;
    text-align: center;
}

/* ==========================================================================
   ACTIONS
   ========================================================================== */

.author-card__actions {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
}

.author-btn {
    display: flex;
    justify-content: center;
    align-items: center;

    height: 60px;
    padding: 0 1.5rem;

    border-radius: 999px;

    text-decoration: none;

    font: var(--font-ui);
    font-size: 1.05rem;
    font-weight: 700;

    transition: var(--transition);
}

.author-btn--secondary {
    background: var(--surface);
    color: var(--text);
    border: 1px solid var(--border);
}

.author-btn--secondary:hover {
    transform:translateY(-3px);
    box-shadow:var(--shadow-sm);
}

.author-btn--primary {
    background: var(--primary);
    color: #fff;
}

.author-btn--primary:hover {
    background: var(--primary-dark);
    transform: translateY(-3px);
    box-shadow:var(--shadow-md);
}

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */

@media (max-width: 768px) {

    .author-card {
        padding: 1.5rem;
    }

    .author-card__header {
        flex-direction: column;
        text-align: center;
    }

    .author-card__name {
        font-size: 1.75rem;
    }

    .author-card__bio {
        padding: 1.4rem;
        border-radius: 22px;
        font-size: 1.05rem;
    }

    .author-card__actions {
        grid-template-columns: 1fr;
    }

}


/*==========================
 Buttons
==========================*/


.author-btn{

    display:flex;

    justify-content:center;

    align-items:center;

    text-decoration:none;

    padding:1rem;

    border-radius:999px;

    font-weight:600;

    transition:var(--transition);

}

/* Outline */



.author-btn-outline:hover{

    background:var(--surface-alt);

}

/* Primary */



.author-btn-primary:hover{

    transform:translateY(-2px);

    box-shadow:var(--shadow-md);

}

/*==========================
 Responsive
==========================*/

@media (max-width:768px){

.author-card{

    padding:2rem;

}






.author-actions{

    grid-template-columns:1fr;

}

